import java.util.*;

public class CountIntervals {
    Set<Integer> covered = new HashSet<>();

    void add(int left, int right) {
        for (int x = left; x <= right; x++) covered.add(x);   // insert every individual integer
    }

    int count() {
        return covered.size();
    }
}

