import java.util.*;

public class CountIntervals {
    List<int[]> intervals = new ArrayList<>();     // sorted, merged, non-overlapping
    long total = 0;

    void add(int left, int right) {
        List<int[]> res = new ArrayList<>();
        int i = 0, n = intervals.size();
        while (i < n && intervals.get(i)[1] < left - 1) res.add(intervals.get(i++));
        int newLeft = left, newRight = right;
        while (i < n && intervals.get(i)[0] <= right + 1) {
            total -= intervals.get(i)[1] - intervals.get(i)[0] + 1;       // remove the old size
            newLeft = Math.min(newLeft, intervals.get(i)[0]);
            newRight = Math.max(newRight, intervals.get(i)[1]);
            i++;
        }
        res.add(new int[]{newLeft, newRight});
        total += newRight - newLeft + 1;                                    // add the new merged size
        while (i < n) res.add(intervals.get(i++));
        intervals = res;
    }

    int count() {
        return (int) total;
    }
}

