#include <bits/stdc++.h>
using namespace std;

class CountIntervals {
public:
    vector<pair<int,int>> intervals;    // sorted, merged, non-overlapping
    long long total = 0;

    void add(int left, int right) {
        vector<pair<int,int>> res;
        int i = 0, n = intervals.size();
        while (i < n && intervals[i].second < left - 1) res.push_back(intervals[i++]);
        int newLeft = left, newRight = right;
        while (i < n && intervals[i].first <= right + 1) {
            total -= intervals[i].second - intervals[i].first + 1;     // remove the old size
            newLeft = min(newLeft, intervals[i].first);
            newRight = max(newRight, intervals[i].second);
            i++;
        }
        res.push_back({newLeft, newRight});
        total += newRight - newLeft + 1;                                 // add the new merged size
        while (i < n) res.push_back(intervals[i++]);
        intervals = res;
    }

    int count() {
        return (int)total;
    }
};
